import{_ as n,o as a,c as p,ai as l}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"开发任务输入规范","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/coding-sop/02-task-brief.md","filePath":"ai/productivity/coding-sop/02-task-brief.md"}'),e={name:"ai/productivity/coding-sop/02-task-brief.md"};function i(r,s,b,c,t,d){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="开发任务输入规范" tabindex="-1">开发任务输入规范 <a class="header-anchor" href="#开发任务输入规范" aria-label="Permalink to “开发任务输入规范”">​</a></h1><blockquote><p>本章解决一个核心问题：如何用尽可能少的文字，把开发任务准确地交给 AI，让它理解目标、识别边界、主动补全信息，并按照明确的标准完成任务。</p></blockquote><h2 id="一、什么时候使用" tabindex="-1">一、什么时候使用 <a class="header-anchor" href="#一、什么时候使用" aria-label="Permalink to “一、什么时候使用”">​</a></h2><p>每次让 Cursor、WorkBuddy 等 AI 编程工具执行开发任务时，都需要先明确任务输入。</p><p>常见场景：</p><ul><li>新增功能：开发一个页面、接口、业务模块。</li><li>Bug 修复：定位并解决一个已知问题。</li><li>功能调整：修改现有逻辑、字段、交互或业务规则。</li><li>代码重构：优化结构，同时保持原有功能和行为。</li><li>系统对接：新增第三方接口、消息通信或数据同步。</li><li>复杂需求：涉及多个模块、数据库、接口和业务流程。</li></ul><p>不需要每次写一份完整需求文档。</p><p>简单任务可以只提供一句话和必要的限制；复杂任务才需要补充业务背景、流程和验收条件。</p><p><strong>判断标准：不是输入越详细越好，而是影响 AI 正确完成任务的信息不能缺失。</strong></p><h2 id="二、任务输入的基本结构" tabindex="-1">二、任务输入的基本结构 <a class="header-anchor" href="#二、任务输入的基本结构" aria-label="Permalink to “二、任务输入的基本结构”">​</a></h2><p>统一采用已有的四段式：</p><ol><li>背景：为什么要做，当前系统是什么情况。</li><li>目标：本次具体要完成什么。</li><li>约束：哪些可以改，哪些不能改，有什么技术和业务限制。</li><li>输出格式：最终需要交付什么。</li></ol><p>在此基础上，增加两个重要要求：</p><ul><li>任务分级：判断本次任务应该采用多重的执行流程。</li><li>验收标准：明确怎样才算真正完成。</li></ul><p>因此，一条完整任务输入可以归纳为：</p><table tabindex="0"><thead><tr><th>部分</th><th>需要回答的问题</th><th>是否必填</th></tr></thead><tbody><tr><td>背景</td><td>当前情况是什么？</td><td>视任务而定</td></tr><tr><td>目标</td><td>具体要实现什么？</td><td>必填</td></tr><tr><td>约束</td><td>哪些能改、哪些不能改？</td><td>必填，至少说明关键边界</td></tr><tr><td>验收标准</td><td>怎样才算完成？</td><td>必填，简单任务可以简写</td></tr><tr><td>输出要求</td><td>最终需要交付什么？</td><td>必填，默认输出执行结果</td></tr><tr><td>任务级别</td><td>需要多大程度的分析和验证？</td><td>由 AI 初步判断</td></tr></tbody></table><p>注意：任务级别可以让 AI 根据风险和影响范围判断，不需要用户每次自己填写。</p><h3 id="_2-1-最小任务输入模板" tabindex="-1">2.1 最小任务输入模板 <a class="header-anchor" href="#_2-1-最小任务输入模板" aria-label="Permalink to “2.1 最小任务输入模板”">​</a></h3><p>日常开发优先使用这个模板：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务：修复订单列表查询时状态筛选失效的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span>让状态筛选按照实际订单状态返回正确结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>只修改订单列表查询相关逻辑，不改变其他筛选条件和接口返回结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>验收：</span></span>
<span class="line"><span>不同订单状态筛选结果正确，原有查询功能不受影响。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先检查现有实现，确认原因后直接修复并测试。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>这已经足以启动一个边界明确的任务。</p><p>如果 AI 发现缺少必要信息，应先检查项目现有代码、配置和业务实现，不能仅仅因为没有提供详细文档就反复追问用户。</p><h3 id="_2-2-复杂任务输入模板" tabindex="-1">2.2 复杂任务输入模板 <a class="header-anchor" href="#_2-2-复杂任务输入模板" aria-label="Permalink to “2.2 复杂任务输入模板”">​</a></h3><p>当任务涉及多个模块、数据库变更、业务流程或系统集成时，使用扩展模板：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>【任务】</span></span>
<span class="line"><span>本次需要完成的具体事项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【背景】</span></span>
<span class="line"><span>当前系统的业务情况、已有功能，以及为什么需要这次调整。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>1. 需要实现的功能。</span></span>
<span class="line"><span>2. 需要解决的问题。</span></span>
<span class="line"><span>3. 预期达到的效果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 允许修改的范围：</span></span>
<span class="line"><span>- 不允许修改的范围：</span></span>
<span class="line"><span>- 必须保持兼容的内容：</span></span>
<span class="line"><span>- 技术或业务限制：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收标准】</span></span>
<span class="line"><span>1. 功能行为：</span></span>
<span class="line"><span>2. 数据正确性：</span></span>
<span class="line"><span>3. 接口兼容性：</span></span>
<span class="line"><span>4. 测试要求：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【交付要求】</span></span>
<span class="line"><span>- 完成代码修改。</span></span>
<span class="line"><span>- 执行必要的编译和测试。</span></span>
<span class="line"><span>- 说明修改文件、实现结果和验证证据。</span></span>
<span class="line"><span>- 汇总未解决的问题和风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先分析任务，识别必要信息和潜在风险，再制定执行方案。</span></span>
<span class="line"><span>不要为了补充无关信息而反复提问。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><p>不需要为了使用模板而填满每一项。没有相关内容的项目可以省略。</p><h2 id="三、不同任务的输入方式" tabindex="-1">三、不同任务的输入方式 <a class="header-anchor" href="#三、不同任务的输入方式" aria-label="Permalink to “三、不同任务的输入方式”">​</a></h2><p>不同开发任务的风险和关注点不同。不要所有任务都使用同一套冗长提示词。</p><h3 id="_3-1-新功能开发" tabindex="-1">3.1 新功能开发 <a class="header-anchor" href="#_3-1-新功能开发" aria-label="Permalink to “3.1 新功能开发”">​</a></h3><p><strong>重点：明确功能行为、业务规则和与现有系统的关系。</strong></p><p>可直接使用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请在当前项目中实现以下功能：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【功能】</span></span>
<span class="line"><span>在订单管理模块增加批量关闭订单功能。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>用户可以选择多条符合条件的订单，执行批量关闭操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 优先沿用现有订单关闭逻辑。</span></span>
<span class="line"><span>- 不改变单条关闭接口的现有行为。</span></span>
<span class="line"><span>- 不允许绕过现有权限校验。</span></span>
<span class="line"><span>- 不得直接修改数据库数据来代替正常业务流程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收】</span></span>
<span class="line"><span>- 可以选择多条符合条件的订单。</span></span>
<span class="line"><span>- 不符合关闭条件的订单不能被关闭。</span></span>
<span class="line"><span>- 部分订单失败时，结果能够明确反馈。</span></span>
<span class="line"><span>- 原有单条关闭功能正常。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先检查现有订单模块、接口和业务规则。</span></span>
<span class="line"><span>如果现有规则能够明确支持本次功能，直接按现有规则实现。</span></span>
<span class="line"><span>如果存在会影响业务正确性的规则冲突，先集中提出问题，不要自行编造规则。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><h3 id="_3-2-bug-修复" tabindex="-1">3.2 Bug 修复 <a class="header-anchor" href="#_3-2-bug-修复" aria-label="Permalink to “3.2 Bug 修复”">​</a></h3><p><strong>重点：先找到根因，再修复；避免只处理表面现象。</strong></p><p>可直接使用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请排查并修复以下问题：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【问题】</span></span>
<span class="line"><span>订单列表切换状态筛选条件后，返回的数据仍然包含其他状态的订单。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【预期行为】</span></span>
<span class="line"><span>选择某一订单状态后，只返回符合该状态的订单。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 先定位问题根因。</span></span>
<span class="line"><span>- 不改变其他查询条件的行为。</span></span>
<span class="line"><span>- 不重构无关代码。</span></span>
<span class="line"><span>- 不通过硬编码绕过问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收】</span></span>
<span class="line"><span>- 不同状态的筛选结果正确。</span></span>
<span class="line"><span>- 分页、排序及其他筛选条件正常。</span></span>
<span class="line"><span>- 原有相关测试通过；必要时补充回归测试。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先检查前后端参数传递、接口实现和 SQL 查询条件。</span></span>
<span class="line"><span>确认根因后直接修复，并提供验证结果。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>如果暂时不能稳定复现，不要让 AI 直接修改代码。应先要求它输出复现条件、排查证据和可能原因。</p><h3 id="_3-3-现有功能调整" tabindex="-1">3.3 现有功能调整 <a class="header-anchor" href="#_3-3-现有功能调整" aria-label="Permalink to “3.3 现有功能调整”">​</a></h3><p><strong>重点：明确变化的部分和必须保持不变的部分。</strong></p><p>可直接使用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请调整客户管理模块的客户列表展示。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>增加客户来源字段，并支持按照客户来源筛选。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 保持原有列表字段和排序逻辑。</span></span>
<span class="line"><span>- 保持现有接口兼容。</span></span>
<span class="line"><span>- 不改变客户新增、编辑和删除流程。</span></span>
<span class="line"><span>- 优先复用现有客户来源数据，不重复创建字段。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收】</span></span>
<span class="line"><span>- 列表正确显示客户来源。</span></span>
<span class="line"><span>- 筛选结果准确。</span></span>
<span class="line"><span>- 原有查询和分页功能正常。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先检查当前字段、数据来源和接口结构，再实施修改。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="_3-4-代码重构" tabindex="-1">3.4 代码重构 <a class="header-anchor" href="#_3-4-代码重构" aria-label="Permalink to “3.4 代码重构”">​</a></h3><p><strong>重点：重构的是内部实现，不是擅自改变业务行为。</strong></p><p>可直接使用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请对订单服务中的重复校验逻辑进行重构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>提取重复逻辑，降低代码重复度，提高可维护性。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 保持现有业务规则不变。</span></span>
<span class="line"><span>- 保持公开接口、方法签名和数据结构兼容。</span></span>
<span class="line"><span>- 不引入没有必要的新依赖。</span></span>
<span class="line"><span>- 不顺手修改无关模块。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收】</span></span>
<span class="line"><span>- 重构前后的业务行为一致。</span></span>
<span class="line"><span>- 相关测试通过。</span></span>
<span class="line"><span>- 没有新增明显的循环依赖或职责混乱。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先梳理重复逻辑及调用关系，确认影响范围后再修改。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>如果现有代码没有足够的测试保障，先补充必要的行为测试，再进行重构。</p><h3 id="_3-5-系统对接与数据同步" tabindex="-1">3.5 系统对接与数据同步 <a class="header-anchor" href="#_3-5-系统对接与数据同步" aria-label="Permalink to “3.5 系统对接与数据同步”">​</a></h3><p><strong>重点：数据结构、通信规则、失败处理和重复执行。</strong></p><p>可直接使用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请实现当前系统与外部设备平台的数据同步接口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【目标】</span></span>
<span class="line"><span>将设备状态同步到当前系统，并能够查询最新设备状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>- 先检查项目现有接口规范和集成方式。</span></span>
<span class="line"><span>- 不改变已有设备数据结构。</span></span>
<span class="line"><span>- 考虑重复请求、超时和异常响应。</span></span>
<span class="line"><span>- 不允许将接口调用成功直接等同于业务数据同步成功。</span></span>
<span class="line"><span>- 不允许修改生产环境数据进行测试。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【验收】</span></span>
<span class="line"><span>- 正常请求能够完成同步。</span></span>
<span class="line"><span>- 重复请求不会造成错误的数据重复处理。</span></span>
<span class="line"><span>- 异常请求有明确的错误记录。</span></span>
<span class="line"><span>- 超时和失败场景能够合理处理。</span></span>
<span class="line"><span>- 有必要的测试覆盖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先梳理通信流程、数据映射和异常处理方案，再开始实现。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h2 id="四、让-ai-主动发现缺失信息" tabindex="-1">四、让 AI 主动发现缺失信息 <a class="header-anchor" href="#四、让-ai-主动发现缺失信息" aria-label="Permalink to “四、让 AI 主动发现缺失信息”">​</a></h2><p>任务输入不可能每次都完整。</p><p>真正高效的方式不是要求用户事先考虑所有细节，而是让 AI 先检查已有信息，再判断是否需要提问。</p><h3 id="_4-1-区分三类信息" tabindex="-1">4.1 区分三类信息 <a class="header-anchor" href="#_4-1-区分三类信息" aria-label="Permalink to “4.1 区分三类信息”">​</a></h3><p>AI 接到任务后，应将信息分成三类：</p><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>处理方式</th></tr></thead><tbody><tr><td>已确认</td><td>用户明确说明，或代码和项目资料能够验证</td><td>直接采用</td></tr><tr><td>可推断</td><td>可以从现有代码、配置和历史实现中合理确认</td><td>检查证据后采用</td></tr><tr><td>待确认</td><td>现有资料无法确定，且不同选择会影响结果</td><td>集中提问</td></tr></tbody></table><p>尤其注意：</p><p><strong>不能把自己的猜测当成已经确认的业务规则。</strong></p><p>例如：</p><ul><li>已确认：订单关闭必须释放库存。</li><li>可推断：当前项目已有统一的库存释放服务。</li><li>待确认：部分发货订单是否允许关闭。</li></ul><p>第三种情况如果会影响库存和订单状态，就不能擅自决定。</p><h3 id="_4-2-统一提问规则" tabindex="-1">4.2 统一提问规则 <a class="header-anchor" href="#_4-2-统一提问规则" aria-label="Permalink to “4.2 统一提问规则”">​</a></h3><p>建议在任务开始时使用以下指令：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>在执行任务前，请先检查现有代码、项目文档和相关业务实现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对于缺失信息，按以下规则处理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 能从现有项目中确认的信息，不要询问我。</span></span>
<span class="line"><span>2. 可以通过安全的代码检查验证的信息，先自行检查。</span></span>
<span class="line"><span>3. 不影响业务正确性的细节，可以采用符合项目现有规范的合理方案。</span></span>
<span class="line"><span>4. 涉及业务规则、数据一致性、权限、安全、不可逆操作或兼容性的重要问题，不能自行猜测。</span></span>
<span class="line"><span>5. 将所有真正阻塞执行的问题集中整理，一次性向我提问。</span></span>
<span class="line"><span>6. 如果没有阻塞问题，直接制定方案并执行，不要逐步询问我是否继续。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果存在非阻塞风险，可以记录并说明处理依据，不要因此中断整个任务。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_4-3-什么情况下必须先问用户" tabindex="-1">4.3 什么情况下必须先问用户？ <a class="header-anchor" href="#_4-3-什么情况下必须先问用户" aria-label="Permalink to “4.3 什么情况下必须先问用户？”">​</a></h3><p>以下情况通常不能自行决定：</p><ul><li>业务规则存在两种以上合理解释。</li><li>修改可能导致历史数据变化或丢失。</li><li>涉及权限、支付、资金、库存等关键业务。</li><li>需要删除数据、执行不可逆操作。</li><li>用户要求与现有系统行为存在冲突。</li><li>需求本身存在无法同时满足的条件。</li></ul><p>以下情况通常不需要询问：</p><ul><li>代码风格可以沿用现有项目规范。</li><li>文件放置位置可以参考相邻模块。</li><li>已有统一组件或服务可以直接复用。</li><li>常规异常处理方式已经在项目中明确。</li><li>可以通过编译、测试或代码检查验证的技术细节。</li></ul><p>目标是让 AI 自己解决技术问题，把真正需要人做决定的问题留给人。</p><h2 id="五、任务分级-简单任务不要走复杂流程" tabindex="-1">五、任务分级：简单任务不要走复杂流程 <a class="header-anchor" href="#五、任务分级-简单任务不要走复杂流程" aria-label="Permalink to “五、任务分级：简单任务不要走复杂流程”">​</a></h2><p>并不是每次开发都需要完整的项目分析、任务拆解和多轮审核。</p><p>建议采用三级任务强度：</p><table tabindex="0"><thead><tr><th>级别</th><th>适用场景</th><th>执行方式</th></tr></thead><tbody><tr><td>L1 简单任务</td><td>单文件小修改、文案调整、明确的小 Bug</td><td>理解目标 → 修改 → 验证</td></tr><tr><td>L2 普通任务</td><td>新增接口、业务功能、跨文件修改</td><td>分析影响 → 制定简要方案 → 实施 → 测试</td></tr><tr><td>L3 复杂任务</td><td>多模块改造、数据库变更、系统集成、核心业务重构</td><td>完整分析 → 方案拆解 → 风险检查 → 分阶段实施 → 全面验证</td></tr></tbody></table><p>让 AI 自动判断任务级别：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请先判断本次任务的执行级别：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>L1：范围明确、影响较小，可以直接实施。</span></span>
<span class="line"><span>L2：涉及多个文件或业务逻辑，需要先分析影响并制定简要方案。</span></span>
<span class="line"><span>L3：涉及多模块、核心业务、数据结构、系统集成或高风险操作，需要完整分析和分阶段执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>判断时考虑：</span></span>
<span class="line"><span>- 修改范围</span></span>
<span class="line"><span>- 业务复杂度</span></span>
<span class="line"><span>- 数据影响</span></span>
<span class="line"><span>- 接口兼容性</span></span>
<span class="line"><span>- 回归风险</span></span>
<span class="line"><span>- 是否存在不可逆操作</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请说明判断结果和原因，然后采用对应的执行流程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要把简单任务复杂化，也不要把复杂任务当成简单任务直接修改。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>任务级别不是根据代码行数判断。</p><p>修改一行代码，如果涉及订单状态、库存扣减或资金计算，也可能是 L3 任务。</p><h2 id="六、明确-ai-的执行边界" tabindex="-1">六、明确 AI 的执行边界 <a class="header-anchor" href="#六、明确-ai-的执行边界" aria-label="Permalink to “六、明确 AI 的执行边界”">​</a></h2><p>除了告诉 AI 要做什么，还需要告诉它哪些事情不能擅自做。</p><p>建议在具体任务中明确以下边界：</p><h3 id="_6-1-修改范围" tabindex="-1">6.1 修改范围 <a class="header-anchor" href="#_6-1-修改范围" aria-label="Permalink to “6.1 修改范围”">​</a></h3><ul><li>可以修改哪些模块？</li><li>是否允许修改数据库表结构？</li><li>是否允许修改接口签名？</li><li>是否允许新增依赖？</li><li>是否允许调整公共组件？</li></ul><p>没有明确授权时，优先选择影响范围最小的实现方案。</p><h3 id="_6-2-执行权限" tabindex="-1">6.2 执行权限 <a class="header-anchor" href="#_6-2-执行权限" aria-label="Permalink to “6.2 执行权限”">​</a></h3><p>以下操作应特别谨慎：</p><ul><li>删除项目文件或历史数据。</li><li>修改生产环境配置。</li><li>执行数据库结构迁移。</li><li>修改认证、权限和安全逻辑。</li><li>大范围重命名、移动或格式化代码。</li><li>升级核心框架和依赖版本。</li><li>执行可能覆盖用户已有数据的命令。</li></ul><p>如果操作具有不可逆性或超出本次授权范围，应先说明影响并等待确认。</p><h3 id="_6-3-修改优先级" tabindex="-1">6.3 修改优先级 <a class="header-anchor" href="#_6-3-修改优先级" aria-label="Permalink to “6.3 修改优先级”">​</a></h3><p>当存在多种实现方案时，优先级建议为：</p><ol><li>复用现有业务逻辑和项目规范。</li><li>在当前模块内完成最小范围修改。</li><li>复用已有公共组件和服务。</li><li>确实无法满足需求时，再考虑新增抽象或依赖。</li><li>需要大范围架构调整时，先说明原因和影响。</li></ol><p>不要为了让代码看起来更漂亮，就扩大本次任务的修改范围。</p><h2 id="七、验收标准-不要让-ai-自己宣布完成" tabindex="-1">七、验收标准：不要让 AI 自己宣布完成 <a class="header-anchor" href="#七、验收标准-不要让-ai-自己宣布完成" aria-label="Permalink to “七、验收标准：不要让 AI 自己宣布完成”">​</a></h2><p>任务完成不等于代码已经写完。</p><p>至少需要区分四个层次：</p><table tabindex="0"><thead><tr><th>验收层次</th><th>检查内容</th></tr></thead><tbody><tr><td>功能验收</td><td>是否实现了用户要求的功能</td></tr><tr><td>兼容验收</td><td>是否影响原有功能、接口和数据</td></tr><tr><td>技术验收</td><td>是否通过编译、测试和必要检查</td></tr><tr><td>交付验收</td><td>是否提供修改范围、验证证据和遗留问题</td></tr></tbody></table><p>根据任务级别选择必要的验收项。</p><h3 id="_7-1-l1-验收" tabindex="-1">7.1 L1 验收 <a class="header-anchor" href="#_7-1-l1-验收" aria-label="Permalink to “7.1 L1 验收”">​</a></h3><ul><li>修改符合任务目标。</li><li>没有扩大修改范围。</li><li>执行必要的局部检查。</li><li>说明修改结果。</li></ul><h3 id="_7-2-l2-验收" tabindex="-1">7.2 L2 验收 <a class="header-anchor" href="#_7-2-l2-验收" aria-label="Permalink to “7.2 L2 验收”">​</a></h3><ul><li>功能行为符合预期。</li><li>相关接口和模块正常。</li><li>编译或相关测试通过。</li><li>检查关键的回归影响。</li><li>说明验证结果和未解决问题。</li></ul><h3 id="_7-3-l3-验收" tabindex="-1">7.3 L3 验收 <a class="header-anchor" href="#_7-3-l3-验收" aria-label="Permalink to “7.3 L3 验收”">​</a></h3><ul><li>核心业务规则得到验证。</li><li>关键数据状态和流转正确。</li><li>接口兼容性得到检查。</li><li>关键异常场景有测试或明确验证。</li><li>相关模块完成回归验证。</li><li>数据库变更和迁移方案经过检查。</li><li>交付内容有明确证据，遗留风险已列出。</li></ul><p><strong>不能执行的测试，不得写成测试通过。</strong></p><p>如果环境缺失、依赖服务不可用或测试数据不足，应明确说明受限原因和已经完成的替代检查。</p><h3 id="_7-4-通用验收指令" tabindex="-1">7.4 通用验收指令 <a class="header-anchor" href="#_7-4-通用验收指令" aria-label="Permalink to “7.4 通用验收指令”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务完成后，请不要直接宣布完成。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按照本次任务的级别执行验收：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 检查实际修改是否符合任务目标。</span></span>
<span class="line"><span>2. 检查是否超出约定的修改范围。</span></span>
<span class="line"><span>3. 执行能够完成的编译、测试和静态检查。</span></span>
<span class="line"><span>4. 检查对原有功能和接口的影响。</span></span>
<span class="line"><span>5. 对无法验证的内容明确说明原因。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终提供：</span></span>
<span class="line"><span>- 完成内容</span></span>
<span class="line"><span>- 修改文件</span></span>
<span class="line"><span>- 关键实现说明</span></span>
<span class="line"><span>- 实际执行的验证命令</span></span>
<span class="line"><span>- 验证结果</span></span>
<span class="line"><span>- 未解决的问题和风险</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不得编造测试结果，不得将未执行的检查描述为通过。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="八、日常使用的最简执行方式" tabindex="-1">八、日常使用的最简执行方式 <a class="header-anchor" href="#八、日常使用的最简执行方式" aria-label="Permalink to “八、日常使用的最简执行方式”">​</a></h2><p>实际使用时，不需要每次复制前面所有提示词。</p><p>建议采用下面的方式：</p><p><strong>第一步：告诉 AI 要做什么。</strong></p><p>一句话说明任务目标，必要时补充背景和约束。</p><p><strong>第二步：让 AI 判断任务级别。</strong></p><p>简单任务直接做，普通任务先分析，复杂任务先形成方案。</p><p><strong>第三步：让 AI 主动检查缺失信息。</strong></p><p>优先从项目代码和文档中寻找答案，只把真正阻塞的问题交给用户。</p><p><strong>第四步：让 AI 按验收标准完成任务。</strong></p><p>不仅要修改代码，还要编译、测试、检查影响并提供证据。</p><p>整个过程可以压缩成下面这段日常指令：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请根据我提供的任务，先检查项目现状并判断任务复杂度。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 优先从项目代码和文档中补全必要上下文。</span></span>
<span class="line"><span>2. 区分已确认信息、可验证信息和待确认信息。</span></span>
<span class="line"><span>3. 只有真正影响业务正确性或执行安全的问题才集中询问我。</span></span>
<span class="line"><span>4. 根据任务复杂度选择最轻量的合理执行流程。</span></span>
<span class="line"><span>5. 严格遵守修改范围，不擅自重构或扩大需求。</span></span>
<span class="line"><span>6. 完成后执行必要的编译、测试和回归检查。</span></span>
<span class="line"><span>7. 最终提供修改内容、验证证据和遗留风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果没有阻塞问题，请直接执行，不要在每个小步骤都等待我的确认。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="九、本章完成检查" tabindex="-1">九、本章完成检查 <a class="header-anchor" href="#九、本章完成检查" aria-label="Permalink to “九、本章完成检查”">​</a></h2><p>每次交给 AI 一个开发任务，可以用下面的清单检查输入是否足够：</p><ul><li>任务目标是否明确？</li><li>必要的背景是否提供，或可以从项目中查到？</li><li>关键修改边界是否明确？</li><li>重要业务规则是否已经确认？</li><li>是否有可以验证的完成标准？</li><li>是否明确了必要的交付结果？</li></ul><p>不要求每一项都写成长篇说明。能够从项目中查到的内容，不必重复提供。</p><p><strong>本章最终要建立的习惯：用户负责说清楚要解决什么问题和关键边界，AI 负责理解项目、补全信息、制定方案、执行和验证。</strong></p><p>下一章将进一步解决：当 AI 接到任务后，如何快速理解一个已有项目，准备真正需要的上下文，避免全仓扫描和无效信息干扰。</p><p>这一章的重点不是让你以后每次都填一张需求表，而是让 AI 养成一套稳定习惯：<strong>先查项目、再判断缺口、集中提问、按风险执行、拿证据验收。</strong></p><p><a href="/my-vitepress-site/ai/productivity/coding-sop/03-context-prep.html">进入第 03 章</a></p>`,128)])])}const m=n(e,[["render",i]]);export{h as __pageData,m as default};
